import React, { useState } from "react";
import MenuIcon from "@mui/icons-material/Menu";
import SearchIcon from "@mui/icons-material/Search";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { styled } from "@mui/material/styles";
import AppBar from "@mui/material/AppBar";
import Box from "@mui/material/Box";
import Toolbar from "@mui/material/Toolbar";
import IconButton from "@mui/material/IconButton";
import { Button, Menu, MenuItem, Stack, OutlinedInput, InputAdornment } from "@mui/material";
import useMediaQuery from "@mui/material/useMediaQuery";
import { Link } from "react-router-dom";

const StyledSearchBar = styled(OutlinedInput)(({ theme }) => ({
  backgroundColor: "white",
  borderRadius: "4px",
  border: "1px solid #ccc",
  width: "300px",
  marginLeft: theme.spacing(2),
  "&:hover": {
    borderColor: "#1eb96b",
  },
  "& .MuiOutlinedInput-input": {
    padding: "8px 14px",
    fontSize: "14px",
    fontFamily: "Roboto, sans-serif",
  },
  "& .MuiOutlinedInput-notchedOutline": {
    borderColor: "#ccc",
  },
  "&:hover .MuiOutlinedInput-notchedOutline": {
    borderColor: "#00C26D",
  },
  "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
    borderColor: "#00C26D",
  },
}));

export default function PrimarySearchAppBar() {
  const [anchorEl, setAnchorEl] = useState(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const isMobile = useMediaQuery("(max-width:1100px)");

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleSearchToggle = () => {
    setIsSearchOpen((prev) => !prev);
  };

  return (
    <Box sx={{ flexGrow: 1 }}>
      <AppBar position="static" sx={{ backgroundColor: "white", boxShadow: "none" }}>
        <Toolbar
          sx={{
            display: "flex",
            flexDirection: { xs: "column", sm: "row" },
            justifyContent: "space-between",
            alignItems: "center",
            paddingX: { xs: 1, sm: 3 },
          }}
        >
          {/* Logo */}
          <Box sx={{ flexGrow: { xs: 1, md: 0 } }}>
            <Link to="/">
              <img
                src="/assets/techcareer-logo.svg"
                alt="logo"
                style={{
                  width: "auto",
                  height: "25px",
                  maxWidth: "200px",
                  paddingLeft: "300px",
                }}
              />
            </Link>
          </Box>

          {/* Desktop Search */}
          {!isMobile && (
            <StyledSearchBar
              placeholder="Etkinlik, İş ilanı, Blog ara"
              startAdornment={
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              }
            />
          )}

          {/* Desktop Buttons */}
          {!isMobile && (
            <Stack direction="row" spacing={1} marginRight={"400px"}>
              <Button variant="text" sx={{ color: "black", whiteSpace: "nowrap" }}>
                Etkinlikler
              </Button>
              <Button variant="text" sx={{ color: "black", whiteSpace: "nowrap" }}>
                İş ilanları
              </Button>
              <Button variant="text" sx={{ color: "black", whiteSpace: "nowrap" }}>
                Eğitimler
              </Button>
              <Button variant="text" sx={{ color: "black", whiteSpace: "nowrap" }}>
                Komünite
              </Button>
              <Button variant="text" sx={{ color: "black", whiteSpace: "nowrap" }}>
                Şirketler
              </Button>
              <div>
                <Button
                  variant="contained"
                  sx={{
                    backgroundColor: "#00C26D",
                    color: "white",
                    whiteSpace: "nowrap",
                    "&:hover": { backgroundColor: "#1aa65f" },
                  }}
                >
                  Giriş/Üye Ol
                </Button>
              </div>
            </Stack>
          )}

          {/* Mobile Icons */}
          {isMobile && (
            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
              <IconButton onClick={handleSearchToggle} sx={{ color: "black" }}>
                <SearchIcon />
              </IconButton>
              <IconButton onClick={handleMenuOpen} sx={{ color: "black" }}>
                <MenuIcon />
              </IconButton>
              <Button
                onClick={handleMenuClose}
                variant="contained"
                sx={{
                  backgroundColor: "#1eb96b",
                  color: "white",
                  whiteSpace: "nowrap",
                  "&:hover": { backgroundColor: "#1aa65f" },
                }}
              >
                Giriş/Üye Ol
              </Button>
            </Box>
          )}

          {/* Mobile Search Overlay */}
          {isMobile && isSearchOpen && (
            <Box
              sx={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                backgroundColor: "white",
                zIndex: 1100,
                display: "flex",
                alignItems: "center",
                padding: "8px 16px",
                boxShadow: "0 2px 4px rgb(0,194,109)",
              }}
            >
              <IconButton onClick={handleSearchToggle} sx={{ color: "black", mr: 1 }}>
                <ArrowBackIcon />
              </IconButton>
              <StyledSearchBar
                autoFocus
                fullWidth
                placeholder="Etkinlik, İş ilanı, Blog ara"
              />
            </Box>
          )}

          {/* Mobile Menu */}
          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
            anchorOrigin={{
              vertical: "top",
              horizontal: "right",
            }}
            transformOrigin={{
              vertical: "top",
              horizontal: "right",
            }}
            PaperProps={{
              sx: {
                width: "200px",
                mt: 2,
              },
            }}
          >
            <MenuItem onClick={handleMenuClose}>Etkinlikler</MenuItem>
            <MenuItem onClick={handleMenuClose}>İş ilanları</MenuItem>
            <MenuItem onClick={handleMenuClose}>Eğitimler</MenuItem>
            <MenuItem onClick={handleMenuClose}>Komünite</MenuItem>
            <MenuItem onClick={handleMenuClose}>Şirketler</MenuItem>
          </Menu>
        </Toolbar>
      </AppBar>
    </Box>
  );
}
